 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full monochrome rows/columns act as panel dividers.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_colors = {grid[r][0] for r in sep_rows}
    col_colors = {grid[0][c] for c in sep_cols}
    div_colors = row_colors | col_colors
    # Most frequent non-divider color is the panel background.
    counts = Counter(v for row in grid for v in row if v not in div_colors)
    if not counts:
        return [row[:] for row in grid]
    bg = counts.most_common(1)[0][0]
    rs = []
    start = 0
    for r in sep_rows:
        if start < r:
            rs.append((start, r))
        start = r + 1
    if start < h:
        rs.append((start, h))
    cs = []
    start = 0
    for c in sep_cols:
        if start < c:
            cs.append((start, c))
        start = c + 1
    if start < w:
        cs.append((start, w))
    if not rs: rs = [(0, h)]
    if not cs: cs = [(0, w)]
    # Find the panel containing the most non-background motif cells.
    best = None
    best_count = 0
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            n = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            if n > best_count:
                best_count, best = n, (ri, ci)
    if best is None:
        return [row[:] for row in grid]
    sri, sci = best
    sr0, sr1 = rs[sri]
    sc0, sc1 = cs[sci]
    motif = [row[sc0:sc1] for row in grid[sr0:sr1]]
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            if (ri, ci) == best:
                continue
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = motif[(r-r0) % len(motif)][(c-c0) % len(motif[0])]
    return out
